"use strict";(globalThis.webpackChunkuniquemath=globalThis.webpackChunkuniquemath||[]).push([[956],{1152:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"documentationSidebar":[{"type":"link","href":"/unique-math/docs/intro","label":"Getting Started","docId":"intro","unlisted":false},{"type":"category","label":"Functions","collapsible":true,"collapsed":false,"items":[{"type":"link","href":"/unique-math/docs/Math/Vector2","label":"Vector2","docId":"Math/Vector2","unlisted":false},{"type":"link","href":"/unique-math/docs/Math/Vector3","label":"Vector3","docId":"Math/Vector3","unlisted":false},{"type":"link","href":"/unique-math/docs/Math/Matrix3","label":"Matrix3","docId":"Math/Matrix3","unlisted":false},{"type":"link","href":"/unique-math/docs/Math/Matrix4","label":"Matrix4","docId":"Math/Matrix4","unlisted":false},{"type":"link","href":"/unique-math/docs/Math/Vector4","label":"Vector4","docId":"Math/Vector4","unlisted":false},{"type":"link","href":"/unique-math/docs/Math/Matrix2","label":"Matrix2","docId":"Math/Matrix2","unlisted":false},{"type":"link","href":"/unique-math/docs/Math/Box2","label":"Box2","docId":"Math/Box2","unlisted":false},{"type":"link","href":"/unique-math/docs/Math/Box3","label":"Box3","docId":"Math/Box3","unlisted":false},{"type":"link","href":"/unique-math/docs/Math/Quaternion","label":"Quaternion","docId":"Math/Quaternion","unlisted":false},{"type":"link","href":"/unique-math/docs/Math/DualQuaternion","label":"DualQuaternion","docId":"Math/DualQuaternion","unlisted":false},{"type":"link","href":"/unique-math/docs/Math/Euler","label":"Euler","docId":"Math/Euler","unlisted":false},{"type":"link","href":"/unique-math/docs/Math/Frustum","label":"Frustum","docId":"Math/Frustum","unlisted":false},{"type":"link","href":"/unique-math/docs/Math/Sphere","label":"Sphere","docId":"Math/Sphere","unlisted":false},{"type":"link","href":"/unique-math/docs/Math/Ray","label":"Ray","docId":"Math/Ray","unlisted":false},{"type":"link","href":"/unique-math/docs/Math/Capsule","label":"Capsule","docId":"Math/Capsule","unlisted":false},{"type":"link","href":"/unique-math/docs/Math/Plane","label":"Plane","docId":"Math/Plane","unlisted":false},{"type":"link","href":"/unique-math/docs/Math/OBB","label":"OBB","docId":"Math/OBB","unlisted":false},{"type":"link","href":"/unique-math/docs/Math/Line3","label":"Line3","docId":"Math/Line3","unlisted":false},{"type":"link","href":"/unique-math/docs/Math/Triangle","label":"Triangle","docId":"Math/Triangle","unlisted":false},{"type":"link","href":"/unique-math/docs/Math/Spherical","label":"Spherical","docId":"Math/Spherical","unlisted":false},{"type":"link","href":"/unique-math/docs/Math/Cylindrical","label":"Cylindrical","docId":"Math/Cylindrical","unlisted":false},{"type":"link","href":"/unique-math/docs/Math/SphericalHarmonics3","label":"SphericalHarmonics3","docId":"Math/SphericalHarmonics3","unlisted":false},{"type":"link","href":"/unique-math/docs/Math/Octree","label":"Octree","docId":"Math/Octree","unlisted":false},{"type":"link","href":"/unique-math/docs/Math/BVH","label":"BVH (Bounding Volume Hierarchy)","docId":"Math/BVH","unlisted":false},{"type":"link","href":"/unique-math/docs/Math/DynamicAABBTree","label":"Dynamic AABB Tree","docId":"Math/DynamicAABBTree","unlisted":false},{"type":"link","href":"/unique-math/docs/Math/DynamicAABBTree2D","label":"DynamicAABBTree2D","docId":"Math/DynamicAABBTree2D","unlisted":false}]}]},"docs":{"intro":{"id":"intro","title":"Getting Started","description":"Welcome to UniqueMath, a robust and evolving math library for GameMaker, inspired by the intuitive design of three.js. UniqueMath brings you powerful mathematical structures\u2014like vectors, matrices, and quaternions\u2014optimized for both performance and readability.","sidebar":"documentationSidebar"},"Math/Box2":{"id":"Math/Box2","title":"Box2","description":"2D axis-aligned bounding box stored as [minX, minY, maxX, maxY].","sidebar":"documentationSidebar"},"Math/Box3":{"id":"Math/Box3","title":"Box3","description":"3D axis-aligned bounding box (AABB) stored as [minX, minY, minZ, maxX, maxY, maxZ].","sidebar":"documentationSidebar"},"Math/BVH":{"id":"Math/BVH","title":"BVH (Bounding Volume Hierarchy)","description":"A Bounding Volume Hierarchy (BVH) is a tree-based spatial partitioning structure where each node is enclosed by a bounding volume (AABB in this implementation). BVHs are highly efficient for raycasting and spatial queries, especially for dynamic or static scenes where objects are distributed non-uniformly.","sidebar":"documentationSidebar"},"Math/Capsule":{"id":"Math/Capsule","title":"Capsule","description":"Bounding capsule stored as [startX, startY, startZ, finishX, finishY, finishZ, radius].","sidebar":"documentationSidebar"},"Math/Cylindrical":{"id":"Math/Cylindrical","title":"Cylindrical","description":"Cylindrical coordinate system represented by an array [radius, theta, y].","sidebar":"documentationSidebar"},"Math/DualQuaternion":{"id":"Math/DualQuaternion","title":"DualQuaternion","description":"Dual Quaternion stored as [rx, ry, rz, rw, dx, dy, dz, dw].","sidebar":"documentationSidebar"},"Math/DynamicAABBTree":{"id":"Math/DynamicAABBTree","title":"Dynamic AABB Tree","description":"A Dynamic AABB Tree is a self-balancing binary search tree where each node is an Axis-Aligned Bounding Box (AABB). It is specifically designed for dynamic environments where objects are frequently added, removed, or moved. It uses \\"fattened\\" AABBs for leaf nodes to minimize the need for tree updates when objects move only slightly.","sidebar":"documentationSidebar"},"Math/DynamicAABBTree2D":{"id":"Math/DynamicAABBTree2D","title":"DynamicAABBTree2D","description":"A high-performance 2D Dynamic AABB Tree (Axis-Aligned Bounding Box Tree) based on Box2D\'s b2DynamicTree. This data structure is specifically designed for spatial partitioning in 2D environments where objects are frequently added, removed, or moved. It uses a self-balancing binary tree with \\"fattened\\" AABBs to minimize tree updates when objects move slightly.","sidebar":"documentationSidebar"},"Math/Euler":{"id":"Math/Euler","title":"Euler","description":"Euler angles describe rotation by applying three axis rotations in a specified order.","sidebar":"documentationSidebar"},"Math/Frustum":{"id":"Math/Frustum","title":"Frustum","description":"Camera view frustum using 6 planes, stored as [[nx, ny, nz, d], ...].","sidebar":"documentationSidebar"},"Math/Line3":{"id":"Math/Line3","title":"Line3","description":"Functions for line segments in 3D space, represented as an array of two Vec3 (start and end).","sidebar":"documentationSidebar"},"Math/Matrix2":{"id":"Math/Matrix2","title":"Matrix2","description":"Functions for 2x2 matrices using 4-element arrays [m0, m1, m2, m3]. All matrices are stored in COLUMN-MAJOR order.","sidebar":"documentationSidebar"},"Math/Matrix3":{"id":"Math/Matrix3","title":"Matrix3","description":"3x3 matrix functions using arrays of 9 elements in column-major order. Rotation angles are in degrees. Functions modify the first matrix in-place for zero allocations.","sidebar":"documentationSidebar"},"Math/Matrix4":{"id":"Math/Matrix4","title":"Matrix4","description":"4x4 matrix functions using arrays of 16 elements in column-major order. Rotation angles are in degrees. Functions modify the first matrix in-place for zero allocations.","sidebar":"documentationSidebar"},"Math/OBB":{"id":"Math/OBB","title":"OBB","description":"Functions for Oriented Bounding Boxes (OBB). An OBB is represented by a 15-element array containing its center, half-extents, and a 3x3 rotation matrix.","sidebar":"documentationSidebar"},"Math/Octree":{"id":"Math/Octree","title":"Octree","description":"An Octree is a hierarchical spatial partitioning data structure used to optimize collision detection and raycasting in 3D space. It recursively subdivides space into eight octants (nodes), allowing for efficient querying of triangles within a specific volume.","sidebar":"documentationSidebar"},"Math/Plane":{"id":"Math/Plane","title":"Plane","description":"Infinite plane stored as [nx, ny, nz, constant]. Equation: nxx + nyy + nz*z + constant = 0.","sidebar":"documentationSidebar"},"Math/Quaternion":{"id":"Math/Quaternion","title":"Quaternion","description":"Rotation stored as [x, y, z, w]. Angles for conversions use degrees.","sidebar":"documentationSidebar"},"Math/Ray":{"id":"Math/Ray","title":"Ray","description":"Ray defined by origin and direction, stored as [ox, oy, oz, dx, dy, dz].","sidebar":"documentationSidebar"},"Math/Sphere":{"id":"Math/Sphere","title":"Sphere","description":"Bounding sphere stored as [x, y, z, radius].","sidebar":"documentationSidebar"},"Math/Spherical":{"id":"Math/Spherical","title":"Spherical","description":"Spherical coordinate system represented by an array [radius, phi, theta].","sidebar":"documentationSidebar"},"Math/SphericalHarmonics3":{"id":"Math/SphericalHarmonics3","title":"SphericalHarmonics3","description":"Functions for 3rd-order Spherical Harmonics (SH), commonly used to represent global irradiance or radiance in real-time.","sidebar":"documentationSidebar"},"Math/Triangle":{"id":"Math/Triangle","title":"Triangle","description":"Functions for 3D triangles represented as an array of three Vec3 (vertices).","sidebar":"documentationSidebar"},"Math/Vector2":{"id":"Math/Vector2","title":"Vector2","description":"2D vector functions using arrays [x, y]. All angles are in degrees. Functions modify the first vector in-place for zero allocations and high performance.","sidebar":"documentationSidebar"},"Math/Vector3":{"id":"Math/Vector3","title":"Vector3","description":"3D vector functions using arrays [x, y, z]. All angles are in degrees. Functions modify the first vector in-place for zero allocations.","sidebar":"documentationSidebar"},"Math/Vector4":{"id":"Math/Vector4","title":"Vector4","description":"Functions for 4D vectors using [x, y, z, w] arrays. All functions modify the first vector in-place to ensure zero allocations and high performance.","sidebar":"documentationSidebar"}}}}')}}]);